			return tools.ErrorResult(fmt.Errorf("write: create parent dirs: %w", err)), nil
		}
	}

	if err := os.WriteFile(resolved, []byte(a.Content), 0o644); err != nil {
		return tools.ErrorResult(fmt.Errorf("write: %w", err)), nil
	}

