	if err := a.Prompt(ctx, "hi"); err != nil {
		t.Fatal(err)
	}
	msgs, _ := st.Messages()
	if len(msgs) != 2 {
		t.Fatalf("expected 2 messages (user + aborted assistant), got %d", len(msgs))
