	}
	if err := json.Unmarshal(ev.Arguments, &parsed); err != nil {
		t.Fatalf("unmarshal arguments: %v", err)
	}
	if parsed.Path != "src/main.go" || parsed.Limit != 20 {
		t.Fatalf("parsed = %+v", parsed)
	}
}

